//~ Embedded Data Unit
//
// The bytes of shell.mdesk's @embed_file entries (fonts, the app icon), about
// 15 MB as hex arrays. They are a translation unit of their own so the unity
// build (uishell_main.c) parses only their declarations in shell.meta.h.
// native/build.sh and native/build.bat compile this once into build/shell_embed.o(bj) and
// rebuild it only when the generated bytes change.
//
// Only the headers String8 needs: base_inc.h defines globals of its own, which
// would clash with the unity build's at link time.

#include "base/base_context_cracking.h"
#include "base/base_core.h"
#include "base/base_arena.h"
#include "base/base_math.h"
#include "base/base_strings.h"

#include "generated/shell.embed.meta.c"
